            "BGH, Beschluss vom 26.03.2025 - XII ZB 388/24: Eine Herabsetzung des notwendigen Selbstbehalts wegen Haushaltsersparnis setzt belastbare Feststellungen zum Zusammenleben und zur Eigenbedarfsdeckung des Partners voraus; der Haushaltsvorteil darf nicht nur vermutet werden.",
            "BGH, Beschluss vom 05.03.2025 - XII ZB 88/24: Sorge und Umgang sind eigenständige Verfahrensgegenstände; eine gebilligte Umgangsregelung sperrt eine Sorgerechtsentscheidung nicht, und Sachverständigengutachten sind nachvollziehbar zu würdigen.",
            "BGH, Beschluss vom 25.09.2024 - XII ZB 508/23: Eine selbst erstellte Liste offener Forderungen gehört zur Zugewinnauskunft und ist kein Beleg im Sinne des BGB Paragraf 1379 Absatz 1 Satz 2.",
            "BGH, Beschluss vom 10.04.2024 - XII ZB 459/23: Bei nicht verheirateten Eltern vertritt im Obhutsmodell der betreuende Elternteil das Kind; im Wechselmodell kann jeder Elternteil den gegen den anderen gerichteten Teilanspruch vertreten, ohne Ergänzungspfleger oder Entscheidung nach BGB Paragraf 1628.",
            "BGH, Beschluss vom 31.01.2024 - XII ZB 385/23: Eine private Umgangsvereinbarung wird nicht allein durch Protokollierung vollstreckbar; erforderlich ist die familiengerichtliche Billigung nach Kindeswohlprüfung. Vertragsstrafen dürfen diese Kontrolle nicht umgehen.",
            "BGH, Beschluss vom 18.10.2023 - XII ZB 197/23: Die Abänderung nach VersAusglG Paragraf 51 erfasst nach Ehezeitende eingetretene tatsächliche oder rechtliche Änderungen, nicht die Korrektur eines Fehlers der Ausgangsentscheidung.",
            "BGH, Beschluss vom 24.03.2021 - XII ZB 230/16: Bei externer Teilung sind Zielversorgung und fiktive interne Teilung auf gleichen Rechnungsgrundlagen zu vergleichen; unverhältnismäßige Transferverluste sind zu vermeiden.",
